 box.querySelectorAll('[data-key]').forEach(el=>el.onchange=()=>{checkpoint();const [group,key]=el.dataset.key.split('.');if(group==='preset'){look.preset=el.value;look.weather={};look.camera={};renderProperties()}else if(group==='capture')scene.camera[key]=+el.value;else look[group][key]=+el.value;changed()});
