async function refreshScenes(){sceneOptions=await api('scenes');$('scene-select').innerHTML=sceneOptions.map(s=>`<option value="${s.id}" ${s.id===scene?.id?'selected':''}>${esc(s.name)}</option>`).join('')}
async function loadScene(id){if(['running','paused','preview','starting'].includes(live.state))throw Error('请先停止当前会话，再切换场景');if(dirty&&!(await confirmChange('当前有未保存修改，仍然切换场景？')))return;scene=await api('scenes/'+id);$('camera-feed').removeAttribute('src');$('camera-feed').style.display='none';$('camera-empty').style.display='flex';previewTime=0;selected=scene.ego;eventId=scene.events[0]?.id;history=[];redo=[];dirty=false;$('dirty').textContent='已保存';render();rebuildActors();focus()}
async function save(){const result=await api('scenes',scene);scene=result.scene;render();dirty=false;$('dirty').textContent='已保存';await refreshScenes();toast('场景已保存；之前版本保留在历史目录')}
async function addActor(modelId='vehicle.tesla.model3'){if(motionLocked())throw Error('当前模式锁定车辆编排');checkpoint();const p=from3(orbit.target),pose=await api('snap',p);const id='actor_'+crypto.randomUUID().slice(0,8),ped=modelId.startsWith('walker');scene.actors.push({id,name:ped?'行人':modelId.includes('firetruck')?'消防车':modelId.includes('ninja')?'摩托车':'新车辆',model:modelId,...pose,color:'#79c8ba',speed:ped?5:40,offset:0,behavior:ped?'walker':'scripted',start_in_motion:!ped,spawn_at_start:true,snap:!ped,acceleration:2.5,deceleration:6,route:[]});selected=id;tab='actor';changed();rebuildActors();render();toast('已添加到视图中心，请拖动到目标位置。新增模型在下次预览时生成。')}
function addEvent(){if(motionLocked())return;checkpoint();const id='event_'+crypto.randomUUID().slice(0,8);scene.events.push({id,name:'新事件',enabled:true,trigger:{type:'time',value:5},action:{type:'speed',actor:selected||scene.ego,value:30}});eventId=id;tab='event';changed();render()}
function toggleRoute(){if(motionLocked())return;routeMode=!routeMode;$('route-mode').classList.toggle('active',routeMode);$('map-hint').textContent=routeMode?'左键点击道路添加路线点 · 再点“绘制路线”结束':'左键选中 / 拖动控件 · 右键平移 · 滚轮缩放';if(routeMode)gizmo.detach();else attach();renderProperties()}
async function start(preview){offlinePlaying=false;if(['running','paused','preview','starting'].includes(live.state))throw Error('请先停止当前会话');await api('validate',scene);const r=await api('start',{scene,preview});lastRun=r.run_id;manual=false;keys.clear();live.state='starting';updateMode();attach();$('camera-feed').src='/api/video?run='+r.run_id;$('camera-feed').style.display='block';$('camera-empty').style.display='none';toast(preview?'正在生成预览布置':'正在启动场景')}
$('snap').onchange=()=>{if(actor()){checkpoint();actor().snap=$('snap').checked;changed()}};
$('scene-select').onchange=guarded(e=>loadScene(e.target.value));$('save').onclick=guarded(save);$('add-actor').onclick=guarded(()=>addActor());document.querySelectorAll('[data-model]').forEach(el=>el.onclick=guarded(()=>addActor(el.dataset.model)));$('add-event').onclick=addEvent;
$('new').onclick=guarded(async()=>{if(['running','paused','preview','starting'].includes(live.state))throw Error('请先停止当前会话，再新建场景');if(dirty&&!(await confirmChange('新建空白场景，放弃当前未保存修改？')))return;const pose=await api('snap',from3(orbit.target));scene={version:2,mode:'motion',dt:.05,id:'scene_'+crypto.randomUUID().slice(0,8),name:'新的驾驶场景',map:map.name,duration:30,seed:42,ego:'ego',actors:[{id:'ego',name:'主车',model:'vehicle.tesla.model3',...pose,speed:30,offset:0,behavior:'scripted',start_in_motion:true,spawn_at_start:true,snap:true,color:'#b4e3d8',route:[],acceleration:2.5,deceleration:6}],events:[],look:{preset:'clear',weather:{},camera:{}},camera:{width:1280,height:720,fps:20,fov:100}};selected='ego';eventId=null;tab='actor';history=[];changed();rebuildActors();render();focus()});
$('duplicate').onclick=guarded(async()=>{checkpoint();scene.id='scene_'+crypto.randomUUID().slice(0,8);scene.name+=' 副本';await save();render()});
