function schedulePlan(){clearTimeout(planTimer);if(!scene)return;planTimer=setTimeout(()=>refreshPlan().catch(e=>{$('plan-state').textContent='需修正编排：'+e.message;$('status-message').textContent=e.message}),400)}
async function refreshPlan(force=false){if(!scene||activeSession())return;const key=JSON.stringify(scene);if(!force&&key===planKey)return;const serial=++planSerial;$('plan-state').textContent='计算道路路线与速度预演…';const result=await api('plan',scene);if(serial!==planSerial||JSON.stringify(scene)!==key)return;planKey=key;planResult=result;sequencer.plan=result;sequencer.render();drawPlannedRoutes();seek(previewTime,false);$('plan-state').textContent=result.locked?'已录制的实际轨迹 · 可拖动时间轴查看':'估计运动预演 · 实际轨迹以 CARLA 录制为准';$('status-message').textContent=result.warnings?.[0]||'路线与时间轴已更新';}
function drawPlannedRoutes(){drawRoutes();if(!planResult)return;for(const [id,track] of Object.entries(planResult.tracks)){const frames=track.frames.filter((_,i)=>i%3===0);if(frames.length<2)continue;const g=new THREE.BufferGeometry().setFromPoints(frames.map(f=>to3({x:f[1],y:f[2],z:f[3]+.2})));routeGroup.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:id===selected?0x7ce5c2:0x64849b,transparent:true,opacity:id===selected?.8:.35})))}requestRender=true}
function sampleFrames(frames,t){let lo=0,hi=frames.length-1;while(lo<hi){const mid=Math.floor((lo+hi)/2);if(frames[mid][0]<t)lo=mid+1;else hi=mid}const b=frames[lo],a=frames[Math.max(0,lo-1)],u=Math.max(0,Math.min(1,(t-a[0])/Math.max(1e-9,b[0]-a[0])));return {x:a[1]+(b[1]-a[1])*u,y:a[2]+(b[2]-a[2])*u,z:a[3]+(b[3]-a[3])*u,yaw:a[4]+((b[4]-a[4]+540)%360-180)*u,speed:a[5]+(b[5]-a[5])*u}}
function seek(t,notify=true){previewTime=t;sequencer.setTime(t);if(['running','paused','starting'].includes(live.state)){if(notify)toast('运行中的播放头由仿真驱动；请停止后预演或使用实机预览');return}
 if(live.state==='preview'){if(notify){clearTimeout(seekTimer);seekTimer=setTimeout(()=>api('command',{type:'seek',time:t}).catch(e=>toast(e.message,true)),100)}return}
 for(const [id,track] of Object.entries(planResult?.tracks||{})){const obj=actorMeshes.get(id);if(!obj||!track.frames.length)continue;const p=sampleFrames(track.frames,t);obj.position.copy(to3(p));obj.rotation.y=p.yaw*Math.PI/180;if(id===scene.ego)$('speed-readout').textContent=Math.round(p.speed)}
 if(t>.001)gizmo.detach();else attach();requestRender=true;
}
let lastAnimation=performance.now();function animateRehearsal(now){const dt=Math.min(.1,(now-lastAnimation)/1000);lastAnimation=now;if(offlinePlaying){seek(Math.min(scene.duration,previewTime+dt));if(previewTime>=scene.duration){offlinePlaying=false;$('rehearse').textContent='▷ 预演'}}requestAnimationFrame(animateRehearsal)}requestAnimationFrame(animateRehearsal);
$('rehearse').onclick=guarded(async()=>{if(activeSession())return;await refreshPlan(true);offlinePlaying=!offlinePlaying;if(offlinePlaying&&previewTime>=scene.duration)previewTime=0;$('rehearse').textContent=offlinePlaying?'Ⅱ 停止预演':'▷ 预演'});
function renderPresets(){const icons={cruise:'→',stop_go:'↗',lead_brake:'Ⅱ',cut_in:'↘',overtake:'⇄',follow:'⇢',parked:'P'};$('preset-list').innerHTML=Object.entries(presets).map(([id,p])=>`<button class="preset-card" data-preset="${id}"><span class="preset-icon">${icons[id]}</span><span><b>${esc(p.name)}</b><small>${esc(p.description)}</small></span></button>`).join('');document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=guarded(async()=>{if(motionLocked())return;const a=actor();if(!a?.model.startsWith('vehicle.'))throw Error('请选择一辆车');let target=scene.actors.find(x=>x.id!==selected&&x.model.startsWith('vehicle.'))?.id;
 if(b.dataset.preset==='follow'){if(!target)throw Error('跟车需要另一辆车');const choices=scene.actors.filter(x=>x.id!==selected&&x.model.startsWith('vehicle.'));if(choices.length>1){showModal('选择跟车目标',`<p class="hint">预设将替换选中车辆的时间轴。旧条件事件中的运动动作会停用。</p><select id="follow-target">${options(Object.fromEntries(choices.map(x=>[x.id,x.name])),target)}</select><button id="confirm-preset" class="primary">应用跟车预设</button>`);$('confirm-preset').onclick=guarded(async()=>{await applyPreset(b.dataset.preset,$('follow-target').value);$('modal').close()});return}}
 await applyPreset(b.dataset.preset,target)}));updateMode()}
