$('modal-close').onclick=()=>$('modal').close();
async function takeLibrary(){if(activeSession())throw Error('请先停止运行');const takes=await api('takes');showModal('选择基准轨迹',`<p class="hint">先在运动编排模式运行并录制。选择实际录制轨迹后，仅调整天气、光照、相机；车辆位置、路线和速度锁定。带手动记录也可以作为新的基准。</p>${takes.length?takes.map(t=>`<div class="take-row"><div><b>${esc(t.name)}</b><small>${esc(t.id)} · ${t.duration.toFixed(1)} s · ${t.frames} 帧 ${t.manual_override?'· 含手动驾驶':''}</small></div><button data-take="${t.id}">锁定此轨迹</button></div>`).join(''):'<p>暂无可用录制，请先运行一个运动场景。</p>'}`);document.querySelectorAll('[data-take]').forEach(b=>b.onclick=guarded(()=>loadTake(b.dataset.take)))}
async function loadTake(id){if(dirty&&!(await confirmChange('切换到录制基准会替换当前编排，继续？')))return;const take=await api('takes/'+id);checkpoint();scene=clone(take.scene);scene.id='env_'+crypto.randomUUID().slice(0,8);scene.name+=' · 环境对照';scene.mode='environment';scene.locked_take=id;selected=scene.ego;tab='look';previewTime=0;planKey='';changed();$('modal').close();rebuildActors();render();focus();await refreshPlan(true);sequencer.fit();toast('已锁定实际轨迹，可在环境面板调整光照与天气')}
