function gamepadControl(){const pad=navigator.getGamepads?.()[inputConfig.index];if(!pad?.connected)return null;const axis=(pad.axes[inputConfig.steerAxis]??0)-inputConfig.steerCenter,dead=inputConfig.deadzone;let steer=Math.abs(axis)<dead?0:Math.sign(axis)*(Math.abs(axis)-dead)/Math.max(.01,inputConfig.steerSpan-dead);if(inputConfig.invert)steer=-steer;const pedal=k=>{if(inputConfig[k+'Mode']==='button')return pad.buttons[inputConfig[k+'Index']]?.value??0;const rest=inputConfig[k+'Rest'],full=inputConfig[k+'Full'];if(Math.abs(full-rest)<.01)return 0;return Math.max(0,Math.min(1,((pad.axes[inputConfig[k+'Index']]??rest)-rest)/(full-rest)))};return {steer:Math.max(-1,Math.min(1,steer)),throttle:pedal('throttle'),brake:pedal('brake')}}
async function sendDrivingInput(){if(inputBusy||!manual||!document.hasFocus()||document.visibilityState!=='visible'||!['running','paused'].includes(live.state)||live.control?.owner!==manualSource)return;let value=manualSource==='keyboard'?{steer:keys.has('a')?-.6:keys.has('d')?.6:0,throttle:keys.has('w')?.75:0,brake:keys.has('s')||keys.has(' ')?1:0}:gamepadControl();if(!value)return;inputBusy=true;try{await api('input',{run_id:live.run_id,epoch:live.control.epoch,seq:++inputSeq,...value})}catch{manual=false}finally{inputBusy=false}}setInterval(sendDrivingInput,50);
